// Trailing 28-day window ending at the close of the last complete week.
// One week is too short to judge whether a SKU is dead. 90 days was more
// accurate but exhausted n8n's memory (~3,700 sales records), so 28 days is
// the working compromise and matches the analyst skill's native period_days.
// The window ENDS on the same Saturday 23:59:59 that the weekly report uses,
// so both files describe the same cut-off moment.

const now = $now.setZone('America/New_York');
const dayOfWeek = now.weekday % 7;
const currentWeekStart = now.minus({ days: dayOfWeek }).startOf('day');

const windowEnd = currentWeekStart.minus({ seconds: 1 });
const windowStart = windowEnd.minus({ days: 28 }).startOf('day');

const fmt = "yyyy-MM-dd'T'HH:mm:ssZZ";

const year = windowEnd.toFormat('yyyy');
const month = windowEnd.toFormat('MM-MMMM');
const fileName = windowEnd.toFormat('yyyy-MM-dd') + '-cigar-inventory.csv';

return [{
  json: {
    start_date: windowStart.toFormat(fmt),
    end_date: windowEnd.toFormat(fmt),
    window_start_label: windowStart.toFormat('yyyy-MM-dd'),
    window_end_label: windowEnd.toFormat('yyyy-MM-dd'),
    period_days: Math.round(windowEnd.diff(windowStart, 'days').days),
    file_path: `business-decisions-data/cigar-inventory/${year}/${month}/${fileName}`,
    generated_at: now.toFormat(fmt)
  }
}];

// Find the Cigars category id. Items carry category_id, not a name, so the
// id has to be resolved before the item list can be filtered.

const cats = items.map(i => i.json);
const match = cats.find(c => String(c.name || '').trim().toLowerCase() === 'cigars');

if (!match) {
  const names = cats.map(c => c.name).join(', ');
  throw new Error('No category named "Cigars" found. Categories present: ' + names);
}

return [{
  json: {
    category_id: match.category_id,
    category_name: match.name
  }
}];

// Join the trailing window's cigar sales to current stock and emit the CSV the
// weekly-cigar-inventory-analyst skill expects:
//   sku, name, units_sold, on_hand, unit_cost
// Every cigar the shop CARRIES is a row, including ones that sold nothing.
// Those are the whole point of the exercise.

const win = $('Build Window').all()[0].json;
const itemRows = $('Fetch Items').all().map(i => i.json);
const sales = items.map(i => i.json);

if (!itemRows.length) {
  throw new Error('No cigar items returned from /items.');
}

// Sum units sold per item_id across the window, cigars only.
const sold = {};
for (const sale of sales) {
  for (const c of (sale.cart_items || [])) {
    if ((c.category_name || '') !== 'Cigars') continue;
    const id = String(c.item_id);
    sold[id] = (sold[id] || 0) + Number(c.quantity || 0);
  }
}

// On-hand lives under item.locations, keyed by location, each with a quantity.
function onHandFor(item) {
  const loc = item.locations;
  if (!loc || typeof loc !== 'object') return 0;
  let total = 0;
  for (const k of Object.keys(loc)) {
    const q = loc[k] && loc[k].quantity;
    const n = Number(q);
    if (!isNaN(n)) total += n;
  }
  return total;
}

function csvCell(v) {
  const s = String(v === null || v === undefined ? '' : v);
  return /[",\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
}

const lines = ['sku,name,units_sold,on_hand,unit_cost'];
let carried = 0;
let zeroSellers = 0;

for (const item of itemRows) {
  if (item.item_inactive === true) continue;
  carried++;

  const id = String(item.item_id);
  const units = Math.round(sold[id] || 0);
  const onHand = Math.max(0, Math.round(onHandFor(item)));
  const cost = Number(item.cost_price || 0);

  if (units === 0) zeroSellers++;

  lines.push([
    csvCell(item.item_number || item.item_id),
    csvCell(item.name),
    units,
    onHand,
    cost.toFixed(2)
  ].join(','));
}

const csv = lines.join('\n') + '\n';

return [{
  json: {
    file_path: win.file_path,
    window_label: `${win.window_start_label} to ${win.window_end_label}`,
    period_days: win.period_days,
    carried_skus: carried,
    zero_sellers: zeroSellers,
    commit_message: `Cigar inventory snapshot ${win.window_end_label} (${carried} SKUs, ${win.period_days}-day window)`,
    file_content: csv
  }
}];

// Shared failure handler for every step in this workflow.

const now = $now.setZone('America/New_York');
const stamp = now.toFormat('yyyy-MM-dd HH:mm:ss ZZZZ');

const first = (items && items[0] && items[0].json) ? items[0].json : {};
const raw = first.error;

let message = 'No error message available';
let detail = '';

if (typeof raw === 'string') {
  message = raw;
  detail = raw;
} else if (raw && typeof raw === 'object') {
  message = raw.message || raw.description || raw.reason || message;
  try {
    detail = JSON.stringify(raw, null, 2).slice(0, 4000);
  } catch (e) {
    detail = 'Could not serialize error payload.';
  }
} else {
  try {
    detail = JSON.stringify(first, null, 2).slice(0, 4000);
  } catch (e) {
    detail = 'Could not serialize item.';
  }
}

let failedNode = 'unknown step';
try {
  if ($prevNode && $prevNode.name) failedNode = $prevNode.name;
} catch (e) {}

let windowLabel = 'unknown';
try {
  const w = $('Build Window').all();
  if (w.length) windowLabel = `${w[0].json.window_start_label} to ${w[0].json.window_end_label}`;
} catch (e) {}

const body = [
  '**Cigar Inventory Snapshot failed.**',
  '',
  `- Failed step: \`${failedNode}\``,
  `- Time: ${stamp}`,
  `- Window: ${windowLabel}`,
  `- Execution ID: ${$execution.id}`,
  '',
  '### Error',
  '```',
  String(message),
  '```',
  '',
  '### Raw payload',
  '```json',
  detail,
  '```',
  '',
  '---',
  'No inventory snapshot was written. The reorder and discontinue analysis has no input until this is resolved.'
].join('\n');

return [{
  json: {
    issue_title: `Cigar Inventory Snapshot failed at ${failedNode} - ${now.toFormat('yyyy-MM-dd')}`,
    issue_body: body
  }
}];
